\title{Knots and Lattices: The Alexander Polynomial as a Signed State Sum, and the Universality of the Signed Model}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The Alexander polynomial $\Delta_K(t)$ of a knot $K$ is a Laurent polynomial invariant encoding topological information. A recurring dream in combinatorial knot theory is to realize $\Delta_K(t)$ as a generating function over lattice states -- a headcount of paths weighted by an ``area'' statistic. We settle the combinatorial status of this program. We formalize two enumeration models on integer coefficient functions $c:\Z\to\Z$: the \emph{unsigned area generating function}, whose coefficient of $t^k$ counts states of area $k$, and the \emph{signed state sum}, whose coefficient of $t^k$ is a signed total $\sum(\pm1)$ over states of area $k$. We prove: (1) every unsigned area generating function has non-negative coefficients, so the naive conjecture fails already for the trefoil ($t-1+t^{-1}$); (2) \emph{universality} -- every finitely supported integer coefficient function is a signed state sum, so the signed model is exactly as expressive as the integer Laurent polynomials and captures every Alexander polynomial; (3) the unsigned model realizes precisely the finitely supported non-negative functions, so the gap between the models is exactly the sign group $\{\pm1\}$; (4) connected sum corresponds to the Cauchy product of signed state sums, with multiplicative total signed weight; (5) the torus family $T(2,2k+1)$, with $\Delta_k(t)=\sum_{i=-k}^k(-1)^{i+k}t^i$, generalizes the trefoil, is palindromic, satisfies $\Delta_k(1)=1$ and $|\Delta_k(-1)|=2k+1$, has a negative coefficient for every $k\ge1$ (never an unsigned count), yet is always a signed state sum.
\end{abstract}

\maketitle

\section{Introduction}

To each knot $K\subset S^3$ the Alexander polynomial associates a Laurent polynomial $\Delta_K(t)\in\Z[t,t^{-1}]$, well-defined up to multiplication by $\pm t^n$. Two structural properties recur here: \emph{reciprocity} $\Delta_K(t)\doteq\Delta_K(t^{-1})$ (palindromic coefficients in a symmetric normalization); and the \emph{normalization/determinant} $\Delta_K(1)=\pm1$, with $|\Delta_K(-1)|$ the knot determinant.

The program we address asks whether $\Delta_K(t)$ can be written combinatorially as a generating function
\[
\Delta_K(t)=\sum_{\text{states }s} w(s)\,t^{a(s)},
\]
where the states range over a finite family (e.g.\ lattice paths in $\Z^2$ avoiding a knot-determined region), $a(s)$ is an integer area statistic, and $w(s)$ a weight. Two choices of weight yield two models with very different expressive power, and our purpose is to determine exactly what each realizes.

We work with \emph{coefficient functions} $c:\Z\to\Z$, where $c(k)$ is the coefficient of $t^k$. Those arising from polynomials are \emph{finitely supported}. We call $c$ \emph{non-negative} if $c(k)\ge0$ for all $k$, and \emph{palindromic} if $c(k)=c(-k)$ for all $k$ (reciprocity in coefficient form).

\section{The two generating-function models}

Let \texttt{states} be a finite set of states with area statistic $a:\iota\to\Z$ and sign assignment $\mathrm{sign}:\iota\to\Z$ (valued in $\{+1,-1\}$ in the intended use).

\begin{definition}[Unsigned area generating function]
$\areaGF(k)=\#\{\,s\in\text{states}:a(s)=k\,\}\in\Z_{\ge0}$; the coefficient of $t^k$ counts states of area $k$.
\end{definition}

\begin{definition}[Signed state sum]
$\signedGF(k)=\sum_{s\in\text{states},\,a(s)=k}\mathrm{sign}(s)$; the coefficient of $t^k$ is the signed total over states of area $k$.
\end{definition}

These model, respectively, an honest lattice-path count and the genuine Alexander state sum $\Delta_K(t)=\sum_s(-1)^{w(s)}t^{a(s)}$.

\begin{proposition}[Unsigned coefficients are non-negative]\label{prop:nonneg}
For any finite state family and area statistic, $\areaGF$ is a non-negative coefficient function.
\end{proposition}
\begin{proof}
Each value is the cardinality of a finite set cast to $\Z$, hence $\ge0$.
\end{proof}

\begin{proposition}[Unsigned $\subseteq$ signed]
$\areaGF(\text{states},a)=\signedGF(\text{states},\mathbf{1},a)$.
\end{proposition}
\begin{proof}
Summing the constant $1$ over states of area $k$ returns their cardinality.
\end{proof}

Proposition~\ref{prop:nonneg} is the crux of the obstruction. The reduced trefoil polynomial $t-1+t^{-1}$ has $c(0)=-1<0$, so it is \emph{not} an unsigned area generating function: the naive conjecture fails at the smallest nontrivial knot.

\section{Universality of the signed state sum}

\begin{theorem}[Universality]\label{thm:univ}
Let $c:\Z\to\Z$ be finitely supported, with support contained in a finite set $\mathrm{supp}\subset\Z$. Then there exist a finite state family, sign assignment, and area statistic with $\signedGF(\text{states},\mathrm{sign},a)=c$.
\end{theorem}
\begin{proof}
Define the universal state family $\text{states}=\bigcup_{k\in\mathrm{supp}}\{(k,j):0\le j<|c(k)|\}\subset\Z\times\mathbb{N}$, with $a(k,j)=k$ and $\mathrm{sign}(k,j)=\sgn(c(k))$. The states of area $m$ are exactly $\{(m,j):0\le j<|c(m)|\}$, of which there are $|c(m)|$, each with sign $\sgn(c(m))$. Hence
\[
\signedGF(m)=|c(m)|\cdot\sgn(c(m))=c(m),
\]
using $\sgn(n)\cdot|n|=n$ for all $n\in\Z$ (covering $c(m)=0$ via the empty family). Distinct $k$ give disjoint fibers because states record their first coordinate, so the sum splits as claimed.
\end{proof}

\begin{corollary}
Every integer Laurent polynomial -- in particular every Alexander polynomial -- is a signed state sum. No Alexander polynomial can escape the signed model.
\end{corollary}

The construction stores each coefficient as (multiplicity)$\times$(sign); the content is that the sign group $\{\pm1\}$ is exactly the cokernel obstruction the unsigned model lacked.

\section{Exact characterization of the unsigned model}

\begin{theorem}[Unsigned representability]\label{thm:areaRep}
If $c:\Z\to\Z$ is finitely supported and non-negative, there exist a finite state family and area statistic with $\areaGF(\text{states},a)=c$.
\end{theorem}
\begin{proof}
Take $\text{states}=\bigcup_{k\in\mathrm{supp}}\{(k,j):0\le j<c(k)\}$ (well-defined since $c(k)\ge0$) with $a(k,j)=k$; states of area $m$ number exactly $c(m)$.
\end{proof}

\begin{theorem}[Characterization]
A coefficient function is an unsigned area generating function iff it is finitely supported and non-negative.
\end{theorem}
\begin{proof}
Necessity of non-negativity is Proposition~\ref{prop:nonneg}; necessity of finite support is immediate. Sufficiency is Theorem~\ref{thm:areaRep}.
\end{proof}

Comparing with Theorem~\ref{thm:univ}: the unsigned model realizes the finitely supported \emph{non-negative} functions, the signed model realizes \emph{all} finitely supported functions, and the difference is exactly the sign group $\{\pm1\}$.

\section{Connected sum and the Cauchy product}

Knots combine by connected sum $K_1\#K_2$, under which $\Delta_{K_1\#K_2}(t)=\Delta_{K_1}(t)\Delta_{K_2}(t)$. The combinatorial counterpart is the Cauchy product on the product state family.

\begin{definition}[Product state family]
Given $S$ (sign $\sigma_S$, area $\alpha_S$) and $T$ (sign $\sigma_T$, area $\alpha_T$), the product family is $S\times T$ with $\text{sign}(i,j)=\sigma_S(i)\sigma_T(j)$ and $\text{area}(i,j)=\alpha_S(i)+\alpha_T(j)$: areas add, signs multiply.
\end{definition}

\begin{theorem}[Convolution / Cauchy product]\label{thm:conv}
For every $m\in\Z$,
\[
\signedGF\big(S\times T,\ \sigma_S\sigma_T,\ \alpha_S+\alpha_T\big)(m)=\sum_{i\in S}\sigma_S(i)\,\signedGF(T,\sigma_T,\alpha_T)\big(m-\alpha_S(i)\big).
\]
\end{theorem}
\begin{proof}
Expand over $S\times T$ and impose $\alpha_S(i)+\alpha_T(j)=m$, i.e.\ $\alpha_T(j)=m-\alpha_S(i)$. Fixing $i$, the inner sum of $\sigma_T(j)$ over states of area $m-\alpha_S(i)$ is $\signedGF(T,\sigma_T,\alpha_T)(m-\alpha_S(i))$; distributing $\sigma_S(i)$ and summing over $i$ gives the identity.
\end{proof}

The right-hand side is the coefficient of $t^m$ in the product of the two signed polynomials, so the product family realizes multiplication, matching connected sum.

\begin{theorem}[Multiplicativity of total signed weight]\label{thm:mult}
\[
\sum_{(i,j)\in S\times T}\sigma_S(i)\sigma_T(j)=\Big(\sum_{i\in S}\sigma_S(i)\Big)\Big(\sum_{j\in T}\sigma_T(j)\Big).
\]
\end{theorem}
\begin{proof}
This is the identity $\sum_{S\times T}f(i)g(j)=(\sum_S f)(\sum_T g)$.
\end{proof}

Evaluating a signed state sum ``at $t=1$'' sums all signs, so Theorem~\ref{thm:mult} is the shadow of $\Delta_{K_1\#K_2}(1)=\Delta_{K_1}(1)\Delta_{K_2}(1)$.

\section{Reciprocity from an area-negating involution}

\begin{theorem}[Palindromy from involution]\label{thm:pal}
Suppose a finite state family admits $\varphi:\iota\to\iota$ that (i) preserves the family, (ii) is an involution on it, (iii) negates area ($a(\varphi(s))=-a(s)$), and (iv) preserves sign. Then $\signedGF$ is palindromic: $\signedGF(k)=\signedGF(-k)$ for all $k$.
\end{theorem}
\begin{proof}
$\varphi$ restricts to a sign-preserving bijection between states of area $k$ and states of area $-k$, matching the signed totals term by term.
\end{proof}

With universality (Theorem~\ref{thm:univ}), which realizes any palindrome as some signed sum, this motivates realizing each palindrome by a \emph{minimal} family with an honest geometric involution.

\section{The torus family $T(2,2k+1)$}

\begin{definition}
The reduced Alexander polynomial of $T(2,2k+1)$ is
\[
\Delta_k(i)=\begin{cases}(-1)^{i+k},&-k\le i\le k,\\0,&\text{otherwise,}\end{cases}
\qquad
\Delta_k(t)=\sum_{i=-k}^{k}(-1)^{i+k}t^i.
\]
\end{definition}

\begin{theorem}[Generalizes the trefoil]
$\Delta_1=t-1+t^{-1}$.
\end{theorem}
\begin{proof}
For $k=1$ the support is $\{-1,0,1\}$ with values $(-1)^{i+1}$: $\Delta_1(\pm1)=1$, $\Delta_1(0)=-1$.
\end{proof}

\begin{theorem}[Reciprocity]
$\Delta_k(i)=\Delta_k(-i)$ for all $i$.
\end{theorem}
\begin{proof}
The window $-k\le i\le k$ is symmetric and $(-1)^{i+k}=(-1)^{-i+k}$ since $i,-i$ have equal parity.
\end{proof}

\begin{theorem}[Normalization]
$\sum_{i=-k}^{k}\Delta_k(i)=1$.
\end{theorem}
\begin{proof}
Reindex $i=j-k$, $j=0,\dots,2k$; the summand becomes $(-1)^j$ and $\sum_{j=0}^{2k}(-1)^j=1$.
\end{proof}

\begin{theorem}[Determinant]
$\sum_{i=-k}^{k}(-1)^i\Delta_k(i)=(-1)^k(2k+1)$, so $|\Delta_k(-1)|=2k+1$.
\end{theorem}
\begin{proof}
For each $i$, $(-1)^i(-1)^{i+k}=(-1)^{2i+k}=(-1)^k$ is constant; summing over the $2k+1$ integers in $[-k,k]$ gives $(-1)^k(2k+1)$.
\end{proof}

\begin{theorem}[Generic negativity]
For every $k\ge1$, $\Delta_k(k-1)=-1$.
\end{theorem}
\begin{proof}
$-k\le k-1\le k$ and $(k-1)+k=2k-1$ is odd, so $(-1)^{(k-1)+k}=-1$.
\end{proof}

\begin{corollary}[Refutation on an infinite family]
For every $k\ge1$, $\Delta_k$ is not an unsigned area generating function.
\end{corollary}
\begin{proof}
It has a negative coefficient, contradicting Proposition~\ref{prop:nonneg}.
\end{proof}

\begin{theorem}[Always a signed state sum]
For every $k$, $\Delta_k$ is a signed state sum.
\end{theorem}
\begin{proof}
$\Delta_k$ is finitely supported (support $\subseteq[-k,k]$), so Theorem~\ref{thm:univ} applies.
\end{proof}

\section{Discussion}

The naive conjecture is false structurally (Proposition~\ref{prop:nonneg}) and generically (the infinite torus family). The signed conjecture is true and maximally expressive (Theorem~\ref{thm:univ}): the only obstruction is positivity, supplied by the sign. The precise gap between the models is $\{\pm1\}$. Connected sum matches the Cauchy product (Theorem~\ref{thm:conv}) with multiplicative total weight (Theorem~\ref{thm:mult}), and reciprocity descends from an area-negating involution (Theorem~\ref{thm:pal}). Universality means the model is expressive, not canonical: each polynomial admits many families, and the interesting question is realizing the invariant by a family reflecting the knot's geometry.

\section{Future directions}

\begin{conjecture}[Sign-balance forces reciprocity, and conversely]
A signed state sum is palindromic iff its family admits an area-negating, sign-preserving involution up to sign cancellation (equal total signed weight over the fibers at $k$ and $-k$); moreover, among families realizing a fixed palindrome there is a minimum-size one that is genuinely involutive. Theorem~\ref{thm:pal} gives one direction and Theorem~\ref{thm:univ} realizes any palindrome as some signed sum; the missing bridge is the minimality/involution refinement.
\end{conjecture}

\begin{conjecture}[Determinant is the only obstruction after $t\mapsto-t$]
For an alternating knot, $t\mapsto-t$ turns $\Delta_K$ into a genuinely non-negative unsigned generating function; the failure of unsigned realizability is entirely explained by the sign pattern captured by $\Delta(-1)$. Alternating knots have strictly alternating signs (Crowell--Murasugi), so a monomial rescaling absorbs $\{\pm1\}$. The family $T(2,2k+1)$ is alternating with coefficients $(-1)^{i+k}$; the rescaling turns it into the all-$+1$ count.
\end{conjecture}

\begin{conjecture}[Connected-sum multiplicativity characterizes the state-sum monoid]
The map sending a knot to its signed state sum is a monoid homomorphism from (knots, connected sum) to (integer Laurent polynomials, product), and the construction can be made functorial so the product state family is the image of connected sum. Theorems~\ref{thm:conv} and~\ref{thm:mult} give the generating-function side; the task is a structured, natural assignment of families to knots.
\end{conjecture}

\section{Conclusion}

The Alexander polynomial is a lattice-state count -- but only with signs. Unsigned counts realize exactly the finitely supported non-negative coefficient functions; signed state sums realize all finitely supported integer functions, hence every Alexander polynomial. The gap is precisely $\{\pm1\}$, connected sum is the Cauchy product, reciprocity descends from an involution, and the torus family $T(2,2k+1)$ displays the whole story. A topological fingerprint becomes, with one bit of sign, a counting problem.

