from __future__ import annotations
from typing import Dict, List, Tuple

CoeffFn = Dict[int, int]
State = Tuple[int, int]  # (area, sign)

def signed_gf(states: List[State]) -> CoeffFn:
    """Coefficient of t^k is the sum of signs over states of area k."""
    out: CoeffFn = {}
    for area, sign in states:
        out[area] = out.get(area, 0) + sign
    return {k: v for k, v in out.items() if v != 0}

def universal_states(c: CoeffFn) -> List[State]:
    """Explicit witness of universality: |c[k]| states of area k, sign of c[k]."""
    st: List[State] = []
    for k, ck in c.items():
        if ck == 0:
            continue
        s = 1 if ck > 0 else -1
        st.extend([(k, s)] * abs(ck))
    return st

if __name__ == "__main__":
    targets = [
        {1: 1, 0: -1, -1: 1},          # trefoil t - 1 + t^-1
        {-2: 3, -1: -5, 0: 7, 2: -1},  # arbitrary integer polynomial
        {0: -13},                       # single negative coefficient
    ]
    for c in targets:
        assert signed_gf(universal_states(c)) == c
        print("reconstructed", c, "from", len(universal_states(c)), "signed states")
    print("Universality verified: every target is a signed state sum.")

from __future__ import annotations
from typing import Dict

CoeffFn = Dict[int, int]

def torus_alex(k: int) -> CoeffFn:
    """Delta_k(t) = sum_{i=-k}^{k} (-1)^{i+k} t^i for the torus knot T(2,2k+1)."""
    return {i: (1 if (i + k) % 2 == 0 else -1) for i in range(-k, k + 1)}

def eval_at(c: CoeffFn, t: int) -> int:
    if t == 1:
        return sum(c.values())
    if t == -1:
        return sum(v * (1 if k % 2 == 0 else -1) for k, v in c.items())
    raise ValueError("only t = +-1 supported")

if __name__ == "__main__":
    for k in range(1, 8):
        d = torus_alex(k)
        assert all(d[i] == d[-i] for i in d)         # reciprocity
        assert eval_at(d, 1) == 1                      # normalization
        assert abs(eval_at(d, -1)) == 2 * k + 1        # determinant
        assert d[k - 1] == -1                          # negative coefficient
        print(f"k={k}: det={2*k+1:2d}  palindromic  Delta(1)=1  has negative coeff")
    print("T(2,3) equals the trefoil:", torus_alex(1) == {1: 1, 0: -1, -1: 1})

