from typing import Dict, List, Tuple

CoeffFn = Dict[int, int]
State = Tuple[int, int]

def signed_gf(states: List[State]) -> CoeffFn:
    out: CoeffFn = {}
    for a, s in states:
        out[a] = out.get(a, 0) + s
    return {k: v for k, v in out.items() if v != 0}

def universal_states(c: CoeffFn) -> List[State]:
    st: List[State] = []
    for k, ck in c.items():
        if ck:
            st.extend([(k, 1 if ck > 0 else -1)] * abs(ck))
    return st

def product_states(s: List[State], t: List[State]) -> List[State]:
    """Connected sum: areas add, signs multiply."""
    return [(a1 + a2, g1 * g2) for a1, g1 in s for a2, g2 in t]

def cauchy(c: CoeffFn, d: CoeffFn) -> CoeffFn:
    out: CoeffFn = {}
    for k1, v1 in c.items():
        for k2, v2 in d.items():
            out[k1 + k2] = out.get(k1 + k2, 0) + v1 * v2
    return {k: v for k, v in out.items() if v != 0}

if __name__ == "__main__":
    tref = {1: 1, 0: -1, -1: 1}
    a, b = universal_states(tref), universal_states(tref)
    assert signed_gf(product_states(a, b)) == cauchy(tref, tref)
    print("connected sum of state families == Cauchy product of polynomials")
    print("trefoil # trefoil =", cauchy(tref, tref))

