def build_signed_state_family(c: CoeffFn) -> List[State]:
    """Construct a signed state family whose signed state sum equals c.

    Complexity: O(sum_k |c[k]|) states and time, i.e. linear in the total
    absolute weight (L1 norm) of the coefficient function.
    """
    family: List[State] = []
    for k, ck in c.items():
        if ck == 0:
            continue
        sign = 1 if ck > 0 else -1
        for _ in range(abs(ck)):
            family.append((k, sign))
    return family

def signed_state_sum(family: List[State]) -> CoeffFn:
    """Signed state sum: coefficient of t^k is the sum of signs over area k."""
    out: CoeffFn = {}
    for area, sign in family:
        out[area] = out.get(area, 0) + sign
    return {k: v for k, v in out.items() if v != 0}

