from typing import Dict, List, Tuple

CoeffFn = Dict[int, int]
State = Tuple[int, int]

def product_family(s: List[State], t: List[State]) -> List[State]:
    """Connected-sum state family: pair every state; areas add, signs multiply.

    Complexity: O(|s| * |t|).
    """
    return [(a1 + a2, g1 * g2) for a1, g1 in s for a2, g2 in t]

def convolution(c: CoeffFn, d: CoeffFn) -> CoeffFn:
    """Cauchy product of two coefficient functions.

    Complexity: O(|supp c| * |supp d|).
    """
    out: CoeffFn = {}
    for k1, v1 in c.items():
        for k2, v2 in d.items():
            out[k1 + k2] = out.get(k1 + k2, 0) + v1 * v2
    return {k: v for k, v in out.items() if v != 0}
